    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP in the C code
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    // Pure definition: initialize all outputs to zero.
    doitgen(p, q, r) = cast<num_t>(0);

    // Reduction definition: accumulate over s.
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // --------------------------------------------------------------------
    // Optimized schedule
    //
    // Goals:
    //   * Good parallelization across (r, q) slices.
    //   * Vectorized, unit-stride access along p.
    //   * Loop order for the reduction that reuses A(r,q,s) across all p
    //     (i.e. iterate s outside p), matching the optimized models.
    // --------------------------------------------------------------------

    // Fused (r, q) index to exploit 2D parallelism across slices.
    Var rq("rq");
    // p tiling for better cache and vectorization
    Var po("po"), pi("pi");

    // Use a modest constant vector width; Halide will adapt if the target
    // doesn't support wide vectors, but this is a good match for AVX2 on x64
    // when num_t is float, and still reasonable for double.
    const int VEC_P  = 8;
    const int TILE_P = 64;

    // Schedule the pure definition (initialization to zero).
    //
    //  - compute_root(): materialize the whole 3D output before any updates.
    //  - fuse(r, q, rq): treat (r, q) pairs as a single dimension for scheduling.
    //  - reorder(p, rq): make p the innermost loop (unit-stride).
    //  - parallel(rq): parallelize across all (r, q) slices.
    //  - vectorize(p): SIMD over contiguous p dimension.
    doitgen
        .compute_root()
        .fuse(r, q, rq)
        .reorder(p, rq)
        .parallel(rq)
        .vectorize(p, VEC_P);

    // Schedule the reduction (update definition).
    //
    // By default, Halide would nest the RDom 's' *inside* the loops over
    // (p, q, r), which leads to the C-like order:
    //
    //   for rq: for p: for s: doitgen[p,q,r] += A[s,q,r] * C4[p,s]
    //
    // This re-reads A[s,q,r] NP times (once per p), wasting bandwidth.
    //
    // We instead reorder to:
    //
    //   for rq: for s: for p: doitgen[p,q,r] += A[s,q,r] * C4[p,s]
    //
    // so that, for each fixed (r,q,s), the value A[s,q,r] can be reused
    // across all p. The mathematical result is identical (sum over s),
    // differing only in floating-point rounding order.
    doitgen
        .update()
        // Tile p into (po, pi) so we can vectorize over pi.
        .split(p, po, pi, TILE_P)
        // Reorder loops for good data locality:
        //   innermost:  pi  -> contiguous p within tile
        //   then:       po  -> tiles of p
        //   then:       s   -> reduction index
        //   outermost:  rq  -> fused (r,q)
        //
        // Final loop nest (conceptually):
        //   for rq:
        //     for s:
        //       for po:
        //         for pi:
        //           p = po*TILE_P + pi;
        //           doitgen[p,q,r] += A[s,q,r] * C4[p,s];
        .reorder(pi, po, s, rq)
        .parallel(rq)
        .vectorize(pi, VEC_P);
        // (Optionally, we could unroll s by a small factor here to
        //  increase ILP, but we keep it simple and robust across NP.)

    // Bind JIT and compile
    doitgen.compile_jit();

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
