 * Original C layout:
 *   A[NR][NQ][NP]  accessed as A[i][j][k]
 *   C4[NP][NP]     accessed as C4[i][j]
 *
 * Halide layout:
 *   A(p, q, r)  with Buffer size (NP, NQ, NR)
 *     mapping: A(p, q, r) == A_c[r][q][p]
 *
 *   C4(p, s) with Buffer size (NP, NP)
 *     mapping: C4(p, s) == C4_c[s][p]
 */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var i("i"), j("j");

    Func init_A("init_A"), init_C4("init_C4");

    // A[i][j][k] = ( (i*j + k) % np ) / np;
    // Mapping: i -> r, j -> q, k -> p  =>  A(p, q, r)
    init_A(p, q, r) =
        cast<num_t>((r * q + p) % np) / cast<int>(np);

    // C4[i][j] = ( (i*j) % np ) / np;
    // Mapping: C4_c[s][p] -> C4(p, s)
    init_C4(i, j) =
        cast<num_t>((j * i) % np) / cast<int>(np);

    // -------------------------
    // Scheduling for init_A/C4
    // -------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Parallelize initialization of A over tiles of q, and vectorize p
    Var qo("qo"), qi("qi");
    const int q_tile = 32;  // reasonable default; handles tails automatically

    init_A
        .split(q, qo, qi, q_tile)
        .parallel(qo)
        .vectorize(p, vec_width);

    // Initialize C4 row-wise and vectorize across the contiguous dimension i
    init_C4
        .parallel(j)
        .vectorize(i, vec_width);

    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
